const vt=()=>reviewCopy[state?.lang||'nl'];
for(const lang of ['nl','fr']){copy[lang].steps.splice(4,0,reviewCopy[lang].step);copy[lang].stageTitles.splice(4,0,reviewCopy[lang].title);copy[lang].stageIntro.splice(4,0,reviewCopy[lang].intro);}
copy.nl.languageNotice='De interface is gewijzigd. Je vrije tekst en getalstrings in Canvas, plan en beoordeling blijven behouden en worden niet automatisch vertaald.';
copy.fr.languageNotice='L’interface a changé. Vos textes libres et chaînes numériques du Canvas, du plan et de l’évaluation sont conservés sans traduction automatique.';

let state,dirty=false,errors=[];
const t=()=>copy[state?.lang||'nl'];
const el=(tag,text,className)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n;};
const button=(text,action,className='button')=>{const n=el('button',text,className);n.type='button';n.addEventListener('click',action);return n;};
const current=()=>M.getCase(state.caseId);
function notify(text){$('status').textContent=text;}
function changed(){dirty=true;state.draftSaved=false;renderContext();}
function value(data){return data?.[state.lang]||'';}
function info(label,text,className){const block=el('div',undefined,'info-block'+(className?' '+className:''));block.append(el('span',label,'info-label'),el('p',text));return block;}
function changeStep(step){errors=[];if(step>=2&&!state.selectedDimensions.length){state.step=1;render();showErrors([{field:'selectedDimensions',code:'count'}]);return;}if(step>=3){const result=M.validate(state);if(!result.valid&&(!state.roadmap||step>=4)){state.step=result.errors.some(e=>e.field==='selectedDimensions')?1:2;errors=result.errors;render();showErrors(errors);return;}if(!state.roadmap){try{state.roadmap=R.create(state);}catch(e){notify(e.message);return;}}if(step>=4){const checked=R.validate(state.roadmap,state);if(!checked.valid){state.step=3;render();showPlanErrors(checked.errors);return;}if(!state.valueReview){try{state.valueReview=V.create(state);}catch(e){notify(e.message);return;}}if(step===5){const reviewChecked=V.validate(state.valueReview,state);if(!reviewChecked.valid){state.step=4;render();showValueErrors(reviewChecked.errors);return;}}}}state.step=step;notify('');render();$('stage-title').focus();}
function renderChrome(){const c=t();document.documentElement.lang=state.lang;document.title='Grow Faster — Canvas · Plan · Value Review · '+(state.lang==='fr'?'Démo':'Demo');$('skip-link').textContent=c.skip;$('demo-label').textContent=c.demo;$('language-switch').setAttribute('aria-label',c.lang);$('prototype-notice').textContent=c.notice;$('intro-eyebrow').textContent=c.introKicker;$('page-title').replaceChildren(document.createTextNode(c.title[0]),el('br'),document.createTextNode(c.title[1]));$('intro-copy').textContent=c.intro;$('method-description').textContent=c.method;$('footer-text').textContent=c.footer;$('footer-limit').textContent=c.footerLimit;document.querySelectorAll('[data-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.language===state.lang)));$('journey').setAttribute('aria-label',c.stepLabel);$('journey').replaceChildren();c.steps.forEach(([title,sub],index)=>{const b=button('',()=>changeStep(index),'step-button');if(index===state.step)b.setAttribute('aria-current','step');b.append(el('span',String(index+1).padStart(2,'0'),'step-number'));const text=el('span',undefined,'step-copy');text.append(el('strong',title),el('small',sub));b.append(text);$('journey').append(b);});}
function renderContext(){const c=t(),item=current(),context=$('context');context.setAttribute('aria-label',c.context);context.replaceChildren(el('p',c.context,'eyebrow'),el('p',value(item.title),'context-title'));const dl=el('dl',undefined,'context-dl');[[c.origin,item.kind==='external'?c.external:c.internal],[c.selection,c.count.replace('{n}',state.selectedDimensions.length)],[c.draft,state.draftSaved?c.saved:c.unsaved]].forEach(([label,text])=>{const row=el('div');row.append(el('dt',label),el('dd',text));dl.append(row);});context.append(dl);const status=el('p');status.append(el('span',c.proposed,'context-status'));context.append(status,el('p',c.contextLimit,'context-footer'));}
function renderSignal(stage){const c=t(),grid=el('div',undefined,'case-grid');cases.forEach(item=>{const b=button('',()=>{if(item.id===state.caseId)return;if(dirty&&!window.confirm(c.caseConfirm))return;state=M.selectCase(state,item.id);dirty=false;errors=[];notify('');render();},'case-card');b.setAttribute('aria-pressed',String(item.id===state.caseId));b.append(el('span',item.kind==='external'?c.external:c.internal,'case-kind'),el('strong',value(item.title)),el('p',value(item.summary)),el('span',item.id===state.caseId?'✓ '+c.selected:c.choose+' →','case-selected'));grid.append(b);});stage.append(grid);const item=current(),detail=el('section',undefined,'evidence-section signal-details');detail.append(el('h3',c.detailTitle),el('p',value(item.summary)));const source=info(c.source,value(item.source),'source');source.append(el('time',item.date,'source-date'));detail.append(source,info(c.evidence,value(item.evidence)),info(c.implication,value(item.implication)),info(c.uncertainty,value(item.uncertainty)));stage.append(detail);}
function renderDiagnostic(stage){const c=t(),grid=el('div',undefined,'diagnostic-grid');grid.id='diagnostic-grid';current().dimensions.forEach((dimension,index)=>{const label=el('label',undefined,'diagnostic-card');const input=el('input');input.type='checkbox';input.id='dimension-'+dimension.id;input.name='dimensions';input.value=dimension.id;input.checked=state.selectedDimensions.includes(dimension.id);if(index===0)input.dataset.errorTarget='selectedDimensions';input.addEventListener('change',()=>{state.selectedDimensions=input.checked?[...state.selectedDimensions,dimension.id]:state.selectedDimensions.filter(id=>id!==dimension.id);changed();const count=$('diagnostic-count');if(count)count.textContent=t().count.replace('{n}',state.selectedDimensions.length)+' · '+t().confidential;});const text=el('span');text.append(el('strong',value(dimension.name)),el('span',value(dimension.observation)));label.append(input,text);grid.append(label);});const count=el('p',c.count.replace('{n}',state.selectedDimensions.length)+' · '+c.confidential,'inline-note');count.id='diagnostic-count';count.setAttribute('aria-live','polite');stage.append(grid,count);}
function field(key,{single=false,hint=''}={}){const wrap=el('div',undefined,'form-field'),id='field-'+key,label=el('label',t().fields[key]);label.htmlFor=id;wrap.append(label);if(hint){const h=el('span',hint,'field-hint');h.id=id+'-hint';wrap.append(h);}const input=el(single?'input':'textarea');input.id=id;input.name=key;input.value=state.fields[key]||'';input.maxLength=12000;input.required=true;if(single)input.type=key==='decisionDate'?'date':'text';else input.rows=['question','owner','success'].includes(key)?3:4;if(hint)input.setAttribute('aria-describedby',id+'-hint');input.addEventListener('input',()=>{state.fields[key]=input.value;changed();input.removeAttribute('aria-invalid');const existing=$(id+'-error');if(existing)existing.remove();if(hint)input.setAttribute('aria-describedby',id+'-hint');else input.removeAttribute('aria-describedby');});wrap.append(input);const error=errors.find(e=>e.field===key);if(error){input.setAttribute('aria-invalid','true');const msg=el('p',errorText(error),'field-error');msg.id=id+'-error';input.setAttribute('aria-describedby',[hint?id+'-hint':'',msg.id].filter(Boolean).join(' '));wrap.append(msg);}return wrap;}
function group(title,intro){const set=el('fieldset',undefined,'field-group');set.append(el('legend',title),el('p',intro,'group-intro'));return set;}
function renderCanvas(stage){const c=t(),item=current();const form=el('form');form.id='canvas-form';form.addEventListener('submit',e=>{e.preventDefault();changeStep(3);});const g1=group(c.group1,c.group1intro);g1.append(field('question'));const linked=el('div',undefined,'readonly-field');linked.append(el('span',c.fields.signal,'field-label'),el('p',value(item.title)+' — '+value(item.implication)),el('small',c.signalHint));g1.append(linked,field('situation'));const g2=group(c.group2,c.group2intro);const choices=el('fieldset',undefined,'options-fieldset');choices.id='field-chosenOption';const choicesLegend=el('legend',c.fields.options,'options-label');choices.append(choicesLegend,el('p',c.optionsHint,'group-intro'));item.canvas.options.forEach(option=>{const label=el('label',undefined,'option-card'),input=el('input');input.type='radio';input.name='chosenOption';input.id='option-'+option.id;input.value=option.id;input.checked=state.chosenOption===option.id;input.addEventListener('change',()=>{state.chosenOption=option.id;changed();});const text=el('span');text.append(el('strong',value(option.label)),el('span',value(option.description)));label.append(input,text);choices.append(label);});g2.append(choices,field('value'),field('resources'),field('risks'),field('unknowns'));const g3=group(c.group3,c.group3intro);g3.append(field('recommendation'));const owner=el('div',undefined,'split-fields');owner.append(field('owner',{single:true}),field('decisionDate',{single:true,hint:c.dateHint}));g3.append(owner,field('success'),el('p',c.confidential,'inline-note'));form.append(g1,g2,g3);stage.append(form);}
function download(){try{const report=M.makeReport(state)+'\n\n'+R.makeReport(state.roadmap,state)+'\n\n'+V.makeReport(state.valueReview,state),blob=new Blob([report],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='grow-faster-canvas-plan-review-'+state.caseId+'-'+state.lang+'.md';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(t().downloaded);}catch(e){changeStep(5);}}
function renderReport(stage){const c=t(),banner=el('div',undefined,'report-banner');banner.append(el('strong',c.reportTitle),el('p',c.reportIntro+' '+vt().limits));const tools=el('div',undefined,'report-tools');tools.append(button(c.download,download,'button primary'),button(c.print,()=>window.print()),button(c.edit,()=>changeStep(2)));const report=el('pre',M.makeReport(state),'report-preview');report.id='report-output';report.setAttribute('aria-label',c.reportLabel);const heading=el('h3',pt().planReport,'roadmap-report-title'),roadmap=el('pre',R.makeReport(state.roadmap,state),'report-preview');roadmap.id='roadmap-report-output';roadmap.setAttribute('aria-label',pt().planReport);const reviewHeading=el('h3',vt().report,'roadmap-report-title'),review=el('pre',V.makeReport(state.valueReview,state),'report-preview');review.id='value-review-report-output';review.setAttribute('aria-label',vt().report);stage.append(banner,tools,report,heading,roadmap,reviewHeading,review);}
function renderActions(){const c=t(),actions=$('workflow-actions');actions.replaceChildren();if(state.step>0)actions.append(button('← '+c.back,()=>changeStep(state.step-1),'button ghost'));const right=el('div',undefined,'right-actions');if(state.step<5){right.append(button(c.save,()=>{state.draftSaved=true;renderContext();notify(vt().saved);}));right.append(button((state.step===2?pt().next:state.step===3?vt().next:state.step===4?vt().toDossier:c.next)+' →',()=>changeStep(state.step+1),'button primary'));}else right.append(button(c.download,download,'button primary'));actions.append(right);}
function render(){const siteReturn=$('site-return');if(siteReturn){siteReturn.href='../approach.html?lang='+state.lang+'#decision-journey-entry';siteReturn.textContent=state.lang==='fr'?'Retour au site':'Terug naar de website';}renderChrome();renderContext();const c=t(),stage=$('stage');stage.replaceChildren();const header=el('header',undefined,'stage-header');header.append(el('p',String(state.step+1).padStart(2,'0')+' / 06 · '+c.steps[state.step][0].toUpperCase(),'stage-kicker'));const title=el('h2',c.stageTitles[state.step]);title.id='stage-title';title.tabIndex=-1;header.append(title,el('p',c.stageIntro[state.step]));stage.append(header);[renderSignal,renderDiagnostic,renderCanvas,renderPlan,renderValueReview,renderReport][state.step](stage);if(state.step<3&&state.step>0){const reset=button(c.reset,()=>{if(window.confirm(c.resetConfirm)){const step=state.step;state=M.selectCase(state,state.caseId);state.step=step===2?1:step;dirty=false;errors=[];render();notify('');}},'button ghost');stage.append(reset);}renderActions();$('error-summary').hidden=true;$('error-summary').replaceChildren();}
function errorText(error){const c=t();if(error.field==='selectedDimensions')return c.diagnosticError;if(error.field==='chosenOption')return c.optionError;if(error.code==='too_long')return c.long;if(error.code==='calendar')return c.calendar;if(error.code==='required')return c.required;return c.genericError;}
function showErrors(list){const c=t(),summary=$('error-summary');summary.replaceChildren(el('h2',c.errors));const ul=el('ul');list.forEach(error=>{const li=el('li'),link=el('a',((c.fields[error.field]||'')?(c.fields[error.field]+': '):'')+errorText(error));link.href=error.field==='selectedDimensions'?'#diagnostic-grid':'#field-'+error.field;link.addEventListener('click',e=>{e.preventDefault();const target=error.field==='selectedDimensions'?document.querySelector('[data-error-target="selectedDimensions"]'):error.field==='chosenOption'?$('option-wait'):$('field-'+error.field);target?.focus();});li.append(link);ul.append(li);});summary.append(ul);summary.hidden=false;summary.focus();}

function planFailure(error){const code=error?.code||error?.message||'';notify(String(code).includes('in_use')?pt().removeInUse:(String(code).includes('limit')||String(code)==='max_actions')?pt().max:pt().planRequired);}
function writePlan(patch){try{state.roadmap=R.updatePlan(state.roadmap,patch);changed();refreshPlanMeta();}catch(e){planFailure(e);}}
function writeAction(id,patch){try{state.roadmap=R.updateAction(state.roadmap,id,patch);changed();refreshPlanMeta();}catch(e){planFailure(e);}}
function dateRange(start,end){try{const d=R.dates(state.roadmap,start,end);return d.start+' → '+d.end;}catch{return pt().datesInvalid;}}
function actionMeta(action){const q=pt();const cross=Math.floor((action.startDay-1)/30)!==Math.floor((action.endDay-1)/30);return q.days+' '+action.startDay+'–'+action.endDay+' · '+dateRange(action.startDay,action.endDay)+(cross?' · '+q.cross:'');}
function refreshPlanMeta(){const q=pt(),plan=state.roadmap;if(!plan)return;const counters=$('roadmap-counters');if(counters){const n=R.summary(plan);counters.replaceChildren();[[q.states.planned,n.planned],[q.states['in-progress'],n.inProgress],[q.states.blocked,n.blocked],[q.states.done,n.reportedDone]].forEach(([label,count])=>{const card=el('div',undefined,'plan-counter');card.append(el('strong',String(count)),el('span',label));counters.append(card);});}for(const action of plan.actions){document.querySelectorAll('[data-dependency-action]').forEach(label=>{if(label.dataset.dependencyAction===action.id)label.textContent=(action.title||q.empty)+' · '+action.id;});const title=$('action-'+action.id+'-summary-title'),meta=$('action-'+action.id+'-dates'),status=$('action-'+action.id+'-summary-status');if(title)title.textContent=action.title||q.empty;if(meta)meta.textContent=actionMeta(action);if(status)status.textContent=q.states[action.status]||q.planning;}for(let i=0;i<3;i++){const date=$('roadmap-review-'+i);if(date){try{date.textContent=q.review+': '+R.dates(plan,(i*30)+1,(i+1)*30).end;}catch{date.textContent=q.datesInvalid;}}}const end=$('roadmap-end');if(end){try{end.textContent=q.end+': '+R.dates(plan,1,90).end;}catch{end.textContent=q.datesInvalid;}}}
function planField(key,label,{action=null,type='textarea',hint=''}={}){const q=pt(),wrap=el('div',undefined,'form-field'),id=action?'action-'+action.id+'-'+key:'roadmap-'+key,input=el(type==='textarea'?'textarea':'input'),lab=el('label',label);lab.htmlFor=id;input.id=id;input.name=id;input.value=action?action[key]:state.roadmap[key];input.maxLength=12000;if(type!=='textarea')input.type=type;else input.rows=['risk','evidence','resources'].includes(key)?2:3;if(type==='number'){input.min=1;input.max=90;input.step=1;}input.required=key!=='evidence';wrap.append(lab);if(hint){const h=el('span',hint,'field-hint');h.id=id+'-hint';wrap.append(h);input.setAttribute('aria-describedby',h.id);}input.addEventListener('input',()=>{const val=type==='number'?Number(input.value):input.value;if(action)writeAction(action.id,{[key]:val});else writePlan({[key]:val});input.removeAttribute('aria-invalid');});wrap.append(input);return wrap;}
function showPlanErrors(list){const q=pt(),summary=$('error-summary');summary.replaceChildren(el('h2',q.planErrors));const ul=el('ul');for(const error of list){let msg=q.planRequired;if(error.field==='sourceFingerprint'||error.code==='stale')msg=q.stale;else if(/depend|cycl|self|preced|finish|unknown/.test(error.code+' '+error.field))msg=q.dependencyError;else if(error.field==='startDay'||error.field==='endDay'||/range|order|integer/.test(error.code))msg=q.rangeError;else if(error.field==='evidence')msg=q.doneError;else if(error.field==='startDate')msg=q.datesInvalid;const label=q.fields[error.field]||q[error.field]||q.action;const li=el('li'),a=el('a',label+': '+msg);const id=error.actionId?'action-'+error.actionId+'-'+error.field:'roadmap-'+error.field;a.href='#'+id;a.addEventListener('click',e=>{e.preventDefault();const target=$(id);if(target){target.closest('details')?.setAttribute('open','');target.focus();}else{$('roadmap-source')?.focus();}});li.append(a);ul.append(li);const target=$(id);if(target){target.setAttribute('aria-invalid','true');target.closest('details')?.setAttribute('open','');}}summary.append(ul);summary.hidden=false;summary.focus();}
